                type="button"
                onClick={closeModal}
                disabled={saving}
                className="rounded-md p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600 disabled:opacity-50"
                aria-label="ปิด"
              >
                <X className="size-4" />
              </button>
            </div>
            
            <div className={`space-y-4 ${activeTab === "workflow" ? "max-w-xl" : "max-w-md"}`}>
              {renderFormFields()}
            </div>
            
            <div className="mt-8 pt-4 border-t border-slate-100 flex justify-end gap-2">
              <button
                type="button"
                onClick={closeModal}
                disabled={saving}
                className="rounded-xl px-5 py-2.5 text-sm font-bold text-slate-600 transition-colors hover:bg-slate-100 disabled:opacity-50"
              >
                ยกเลิก
              </button>
              <button

                type="button"
                onClick={handleSave}
                disabled={saving || !isModalValid}
                className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-bold text-white transition-colors hover:bg-blue-700 disabled:opacity-60"
              >
                {saving && <Loader2 className="size-4 animate-spin" />}
                {saving ? "กำลังบันทึก..." : "บันทึกข้อมูล"}
              </button>
            </div>
          </div>
        ) : activeTab === "running" ? (
          <DocumentRunningTab showToast={showToast} />
        ) : activeTab === "workflow" ? (
          <WorkflowTab
            rows={rows as WorkflowRow[]}
            docTypes={data.doctype as any}
            showDeleted={showDeleted}
            onShowDeletedChange={setShowDeleted}
            stats={tabStats}
            onEdit={openEdit}
            onDelete={softDelete}
            onRestore={restore}

            canEdit={hasPerm('workflow', 'edit')}
            canDelete={hasPerm('workflow', 'delete')}
          />
        ) : (
          <>
            <div className="flex flex-wrap items-center justify-between gap-4">
              <h2 className="text-sm font-medium text-slate-800">{tabLabel}</h2>
              <InactiveFilterCheckbox checked={showDeleted} onChange={setShowDeleted} />
            </div>

            <MasterDataTableWrap
              empty={rows.length === 0}
              emptyContent={
                <div className="flex flex-col items-center justify-center gap-3 px-6 py-12 text-center">
                  <Inbox className="size-10 text-slate-300" />
                  <p className="text-sm text-slate-500">
                    {showDeleted ? "ไม่มีรายการที่ปิดใช้งาน" : "ไม่มีข้อมูล"}
                  </p>
                  <p className="text-xs text-slate-400">
                    {showDeleted
                      ? "รายการที่กู้คืนจะแสดงในรายการปกติ"
                      : activeTab === "signature"
                        ? "เพิ่มลายเซ็นได้ที่หน้าโปรไฟล์"
                        : "กดปุ่ม เพิ่ม เพื่อสร้างรายการใหม่"}
                  </p>
                </div>
              }
              mobile={<MasterDataMobileCardList rows={mobileRows} />}
            >
              <table className={MD_TABLE}>
                <thead className={MD_THEAD}>
                  <tr>
                    {renderHeaders()}
                    <th className={MD_TH_STATUS}>สถานะ</th>
                    <th className={thAction}>จัดการ</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr
                      key={row.id}
                      className={`group ${MD_TR}`}
                    >
                      {renderCells(row)}
                      <td className={MD_TD_STATUS}>
                        <StatusBadge active={row.isActive} />
                      </td>
                      <td className={MD_TD_ACTION}>
                        {row.isActive ? (
                          (() => {
                            let canEdit = false;
                            let canDelete = false;
                            if (activeTab === 'department') {
                              canEdit = hasPerm('departments', 'edit');
                              canDelete = hasPerm('departments', 'delete');
                            } else if (activeTab === 'position') {
                              canEdit = hasPerm('positions', 'edit');
                              canDelete = hasPerm('positions', 'delete');
                            } else if (activeTab === 'doctype') {
                              canEdit = hasPerm('doc_types', 'edit');
                              canDelete = hasPerm('doc_types', 'delete');
                            } else if (activeTab === 'signature') {
                              canEdit = hasPerm('signatures', 'edit');
                              canDelete = hasPerm('signatures', 'delete');
                            }
                            
                            const guard = getDeleteGuard(
                              activeTab as DataTabKey,
                              row,
                              signatureGuardData
                            );
                            return (
                              <RowActions
                                onEdit={canEdit ? () => openEdit(row.id) : undefined}
                                onDelete={canDelete && activeTab !== "position" ? () => softDelete(row.id) : undefined}
                                deleteBlocked={guard.blocked}
                                deleteTooltip={guard.tooltip}
                              />
                            );
                          })()
                        ) : (
                          <RowActions onRestore={() => restore(row.id)} />
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </MasterDataTableWrap>
          </>
        )}
      </section>
    </MasterDataLayout>
      {previewSignatureUrl && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4 sm:p-6 backdrop-blur-xs"
          style={{ paddingLeft: isOpen ? "calc(16rem + 1.5rem)" : "calc(5rem + 1.5rem)" }}
          onClick={() => setPreviewSignatureUrl(null)}
        >
          <div
            className="relative flex flex-col max-h-[85vh] w-full max-w-sm rounded-2xl border border-slate-200 bg-white p-6 shadow-2xl items-center"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex w-full shrink-0 items-start justify-between gap-3 pb-3 border-b border-slate-100">
              <h2 className="text-sm font-bold text-slate-800">
                ตัวอย่างลายเซ็นของ {previewSignatureName}
              </h2>
              <button
                type="button"
                onClick={() => setPreviewSignatureUrl(null)}
                className="rounded-md p-1 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
                aria-label="ปิด"
              >
                <X className="size-4" />
              </button>
            </div>
            <div className="my-8 flex w-full items-center justify-center rounded-xl border border-slate-200 bg-slate-50/50 p-6 shadow-inner relative overflow-hidden select-none">
              <img
                src={previewSignatureUrl}
                alt={previewSignatureName}
                className="h-32 max-w-full object-contain pointer-events-none"
              />
              {/* Security Watermark Overlay */}
              <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center rotate-[-15deg] opacity-20 font-black text-rose-600 text-xs sm:text-sm tracking-widest uppercase select-none leading-relaxed text-center p-2">
  {/* eslint-disable-next-line @next/next/no-img-element */}
                <span>FOR PREVIEW ONLY</span>
                <span>ห้ามคัดลอก / ตัวอย่างลายเซ็นระบบ</span>
                <span className="text-[10px]">SECURITY WATERMARK</span>
              </div>
            </div>
            <button
              type="button"
              onClick={() => setPreviewSignatureUrl(null)}
              className="w-full rounded-xl bg-slate-100 py-2.5 text-xs font-bold text-slate-700 hover:bg-slate-200 transition-colors"
            >
              ปิดหน้าต่าง
            </button>
          </div>
        </div>
      )}
    </>
  );
}

function Field({
  label,
  value,
  onChange,
  type = "text",
  inputClassName,
  error,
  maxLength,
  onBlur,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  inputClassName?: string;
  error?: string;
  maxLength?: number;
  onBlur?: () => void;
}) {
  return (
    <div className="mb-3">
      <label className="mb-1.5 block text-xs text-slate-500">{label}</label>
      <input
        type={type}
        className={
          inputClassName ??
          "w-full rounded-md border border-gray-200 px-3 py-2 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
        }
        value={value}
        maxLength={maxLength}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error && <p className="mt-1 text-xs text-red-500">{error}</p>}
    </div>
  );
}

"use client";

import React, { useState, useMemo } from "react";
import Link from "next/link";
import { 


  FileText, 
  Clock, 
  DollarSign, 
  Download, 
  Filter, 
  AlertCircle,
  CheckCircle2,
  Clock4,
  XCircle,
  RefreshCcw,
