  { id: "turnaround", title: "Approval Turnaround", icon: Clock, desc: "สถิติระยะเวลาการอนุมัติ" },
  { id: "spend", title: "Purchase Spend", icon: DollarSign, desc: "รายงานมูลค่าจัดซื้อ (PR/PO)" },
